  const results = [];
  for (const entry of sourceList(runId)) {
    if (!entry.pmid && !entry.doi) {
      results.push({ id: entry.id, status: "skipped", details: [] });
      continue;
    }
    const query = entry.pmid ? `EXT_ID:${entry.pmid} AND SRC:MED` : `DOI:"${entry.doi}"`;
    const data = await getJson2(searchUrl(query).href), record2 = data.resultList?.result?.[0];
    if (!record2) {
      results.push({ id: entry.id, status: "not_found", details: [] });
      continue;
    }
    const details = compareMeta(entry, record2);
    results.push({ id: entry.id, status: details.length ? "mismatch" : "ok", details });
  }
